// A stand-in web bundle: renders the route's testID and lays the page out in the browser's language.
(function render() {
  var isArabic = (navigator.language || '').toLowerCase().indexOf('ar') === 0;
  document.documentElement.lang = isArabic ? 'ar' : 'en';
  document.documentElement.dir = isArabic ? 'rtl' : 'ltr';
  var screen = document.createElement('div');
  screen.setAttribute('data-testid', location.pathname.indexOf('settings') === -1 ? 'tasks.list' : 'settings.list');
  document.getElementById('root').appendChild(screen);
})();
